INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(3373, 'plPL', 'Esencja Eranikusa', 'Gdy dotykasz klejnotu, w twoim umyśle rozbrzmiewa głęboki głos.$B$B„$GŚmiertelniku:Śmiertelniczko;, wysłuchaj tej prośby. Jestem Eranikus z Zielonego Stada, strażnik tej przeklętej świątyni. Moja misja, by trolle nigdy więcej nie sprowadziły na świat swego plugawego boga, na razie zakończyła się porażką. Gdy nasycam ten klejnot cząstką swojej esencji, czuję, jak moja więź ze Snem wykręca się w chaos. Proszę – umieść ten klejnot w źródle esencji w moim leżu i pozwól, by nasza tamtejsza magia oczyściła moją jaźń ze skazy, abym mógł spocząć”.', 'Umieść esencję Eranikusa w źródle esencji w jego leżu w Zatopionej Świątyni.', '', '', '', '', '', '', 0),
(8713, 'plPL', 'Nestor Gwiezdna Pieśń', '', '', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(3373, 'plPL', 'Umieszczasz klejnot w źródle esencji.$B$B„Dziękuję ci, $gśmiertelniku:śmiertelniczko;, $gdokonałeś:dokonałaś;... nie... to, to niemożliwe! Nie! Zepsucie tego przeklętego boga kala nawet świętość źródła esencji Zielonego Stada! Nie, proszę, czuję, jak moja esencja jest ze mnie wydzierana! CO ZA BÓL! Czuję, jak ogarnia mnie uścisk wiecznego koszmaru...”$B$B„$GŚmiertelniku:Śmiertelniczko;, błagam cię! Znajdź kogoś z Zielonego Stada, by to powstrzymać... pomóż mi... jestem skuty w ciemności... na wieki w udręce... proszę, nie dręcz...”', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(3373, 'plPL', 'Gdy zbliżasz się do źródła esencji, o którym mówił ci Eranikus, jego głos znów dotyka twojego umysłu.$B$B„Tak, $gśmiertelniku:śmiertelniczko;, to źródło esencji odkupi tę nieskażoną cząstkę mojej jaźni, która wciąż tkwi w tym klejnocie. Umieść klejnot w źródle i pozwól, by magia Zielonego Stada oczyściła moją istotę z zepsucia i skazy. Tylko wtedy zaznam prawdziwego wyzwolenia i tylko wtedy Stado zdoła na nowo roztoczyć pieczę nad Atal\'ai”.', 0);
