INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(4364, 'plPL', 'Nie wiecie, co czynicie! Musimy was zniszczyć dla waszego własnego dobra.', '', 0),
(4416, 'plPL', 'Przy wejściu do komnaty w milczeniu stoi pradawny Ołtarz Hakkara.$B$BSpoglądając na balkony nad nim, dostrzegasz, że na każdym spoczywa duży posąg przypominający węża. Posągi bardzo przypominają te na ołtarzu przed tobą. Muszą być w jakiś sposób powiązane...', 'Przy wejściu do komnaty w milczeniu stoi pradawny Ołtarz Hakkara.$B$BSpoglądając na balkony nad nim, dostrzegasz, że na każdym spoczywa duży posąg przypominający węża. Posągi bardzo przypominają te na ołtarzu przed tobą. Muszą być w jakiś sposób powiązane...', 0),
(4417, 'plPL', 'Jak ołtarz i posągi mogą być ze sobą powiązane?', 'Jak ołtarz i posągi mogą być ze sobą powiązane?', 0),
(4426, 'plPL', 'Po drugiej stronie komnaty pojawia się jasne światło, po czym znika. Potem dostrzegasz kolejny promień... i jeszcze jeden.$B$BWygląda na to, że pokazują ci jakiś wzór.', 'Po drugiej stronie komnaty pojawia się jasne światło, po czym znika. Potem dostrzegasz kolejny promień... i jeszcze jeden.$B$BWygląda na to, że pokazują ci jakiś wzór.', 0),
(4485, 'plPL', 'Moje wygnanie dobiegło końca! Niech płynie krew!', '', 0),
(4490, 'plPL', 'Tarcza opaść! Powstańcie, Atal\'ai! Powstańcie!', '', 0),
(4703, 'plPL', 'Nie można pozwolić, by to zło wkroczyło na ten świat! Przybywajcie, moje dzieci!', '', 0),
(6216, 'plPL', 'Nażrę się waszymi kośćmi!', '', 0),
(6217, 'plPL', 'Nadchodzi Duszożerca!', '', 0),
(6219, 'plPL', 'Hakkar znów będzie żył!', '', 0),
(6220, 'plPL', 'Zawróćcie! Nie budźcie śniącego!', '', 0),
(6538, 'plPL', 'Dołączcie do nas!', '', 0),
(11552, 'plPL', 'Gdzie jest Nestor Rykogniew?', 'Gdzie jest Nestor Rykogniew?', 0),
(11553, 'plPL', 'Nestor Rykogniew czuwa nad Mrocznym Portalem z grzbietu na Jałowych Ziemiach.', 'Nestor Rykogniew czuwa nad Mrocznym Portalem z grzbietu na Jałowych Ziemiach.', 0);
